'use strict';
nav.splice(6,0,['scaling','07','Imperiet']);nav.forEach((n,i)=>n[1]=String(i+1).padStart(2,'0'));
const priorScaleRender=render;
let territoryRing=1;
function scaling(){const a=s.scale,score=G.empireScore(s),held=s.stock.reduce((n,q)=>n+q,0)+s.stash.reduce((n,q)=>n+q,0),volume=s.routes.filter(r=>r.active).reduce((n,r)=>n+r.qty,0)+held;
return `<div class="page-title"><div><span class="section-kicker">REINVESTERING / ${a.mode==='dynasty'?'ARVERUNDE · '+a.legacy+' ALLIANSEBONUSER':'STANDARDRUNDE · LIKT UTGANGSPUNKT'}</span><h1>BYGG VIDERE.<br>IKKJE BARE TELL PENGER.</h1><p>De første ti nivåene bygges med gradvise kostnadsøkninger. Senere nivåer blir dyrere og gir mindre ekstra kapasitet. Bygg det nettverket trenger, og velg hvem som skal lede det.</p></div><div class="ledger-total"><span>PRODUKTIV IMPERIEVERDI</span><strong>${kr(score.value)}</strong></div></div>
<section class="council-strip"><span>Aktive områder <b>${score.areas} / ${score.totalAreas}</b></span><span>Kontrollspenn <b>${Object.keys(a.territories).length} / ${G.controlLimit(s)}</b></span><span>Reinvestert kapital <b>${kr(a.invested)}</b></span><span>Høyeste ring <b>${G.RINGS[score.ring]}</b></span></section>
<section class="capacity-grid"><article class="council-card"><h2>Lager</h2><p>${held.toLocaleString('nb-NO')} av ${G.storageCapacity(s).toLocaleString('nb-NO')} kapasitetsenheter brukt.</p>${meter(held/G.storageCapacity(s)*100)}<p>Fullt lager bremser ny produksjon. Eksisterende varer slettes ikke; eksternt lager koster 0,05 kr per overskytende enhet og uke.</p></article><article class="council-card"><h2>Distribusjon</h2><p>${volume.toLocaleString('nb-NO')} planlagte enheter · ${G.distributionCapacity(s).toLocaleString('nb-NO')} i eget apparat.</p>${meter(volume/G.distributionCapacity(s)*100)}<p>Alt selges fortsatt automatisk. Volum utover egen kapasitet bruker underleverandører og kan koste opptil 12 % ekstra av brutto.</p></article></section>
<section class="active-project"><h2>Hvem sitter ved de nye bordene?</h2><p>Større rekkevidde krever at du deler ansvar. Ledelsen bygger avtalen gjennom åtte uker med faktiske leveranser til minst to byer og minst 55 lojalitet.</p>${G.regionalInfo(s).project?`<p><b>Under oppbygging:</b> ${G.REGIONAL_MODELS.find(m=>m.id===s.regional.project.model).name} · ${s.regional.project.progress} av 8 driftsuker.</p>`:''}<div class="project-grid">${G.regionalInfo(s).options.map(q=>`<article class="council-card"><span class="section-kicker">${q.active?'SLIK LEDER DU NÅ':'EN ANNEN MÅTE Å VOKSE PÅ'}</span><h3>${q.name}</h3><p>${q.text}</p><p>Plass til ${q.limit} regioner. Oppbygging ${kr(q.cost)}; dette er en organisasjonskostnad.</p>${q.reason?`<p class="small">${q.reason}</p>`:''}${btn('regionalPlan',q.id,q.active?'Avtalen er aktiv':'Bygg denne avtalen',!q.valid,'button ghost')}</article>`).join('')}</div></section>${s.rankLevel>=5||s.legacyFund?.id?`<section class="active-project"><span class="section-kicker">ET LØFTE SOM FORTSETTER UTEN DEG</span><h2>Hva skal de andre sitte igjen med?</h2><p>Du velger én mottaker. Første innbetaling er åtte millioner; deretter går en synlig andel av fri kasse til mottakeren hvert kvartal. Driftsreserve og utestående gjeld holdes utenfor. Midlene tilhører mottakeren og gir ikke private eiendelspoeng.</p>${s.legacyFund.id?`<p><b>${G.legacyFundInfo(s).choice.name}</b> · ${kr(s.legacyFund.paid)} gitt videre · ${s.legacyFund.active?'neste kvartal ved dagens kasse: '+kr(G.legacyFundInfo(s).nextContribution):'innbetalingene er pauset'}.</p>${s.legacyFund.active?btn('legacyPause','','Sett nye innbetalinger på pause',s.ended,'button ghost'):''}`:''}<div class="project-grid">${G.legacyFundInfo(s).options.map(q=>`<article class="council-card"><h3>${q.name}</h3><p>${q.text}</p><p>${Math.round(q.rate*100)} % av fri kasse hvert kvartal. Første innbetaling ${kr(q.initial)}.</p>${q.reason?`<p class="small">${q.reason}</p>`:''}${btn('legacyFund',q.id,s.legacyFund.id===q.id?'Følg opp løftet':'Gi dette løftet',!q.valid,'button brass')}</article>`).join('')}</div></section>`:''}<section class="active-project"><h2>Gi lederne en kapitalplan.</h2><p>Én investering hver fjerde uke, maksimalt 60 % av kapitalen utover driftsreserven. Lederne tar høyde for 13 ukers faste utgifter og to innkjøps- og produksjonsoppgjør. Du bestemmer retningen.</p><div class="market-actions">${['manual','capacity','expansion'].map(id=>btn('capitalPolicy',id,({manual:'Velg selv',capacity:'Balanser kapasiteten',expansion:'Prioriter ekspansjon'})[id]+((a.reinvestment||'manual')===id?' ✓':''),s.rankLevel<3,'button ghost')).join('')}</div><p class="small">Driftsreserve nå: ${kr(G.capitalReserve(s))}.</p></section><h2 class="section-heading">Kapasitet og rammeavtaler</h2><div class="investment-grid">${G.INFRA.map(i=>{const q=G.infraQuote(s,i.id);return `<article class="council-card"><span class="section-kicker">NIVÅ ${q.level} / UTEN FAST TAK</span><h2>${i.name}</h2><p>${i.text}</p><p class="small">Neste nivå gir også ${kr(q.weekly)} / uke i rammeavtaler og utleie før driftsstrategi. Utleie alene: ${Math.ceil(q.payback)} uker til tilbakebetaling. Med dagens vareflyt: ${Number.isFinite(q.operationalPayback)?'ca. '+Math.ceil(q.operationalPayback)+' uker':'ingen lønnsom tilbakebetaling'} (${kr(q.operatingGain)} ekstra netto / uke). ${q.withinHorizon?"Anslaget rekker innen 2036.":"Dette tjener seg ikke inn før 2036 med dagens drift."} ${q.strategic?"Nivået kan likevel åpne et større nettverk.":"Utvid når du faktisk trenger kapasiteten."} Anslaget bruker dagens marked og er ingen garanti.</p>${btn('invest',i.id,'Bygg neste · '+kr(q.cost),s.rankLevel<3||s.cash<q.cost||!G.infraAllowed(s,i.id),'button brass')}</article>`;}).join('')}</div>
<h2 class="section-heading">Territorium i ringer</h2><p class="rule-note">To historiske etableringer i forrige ring åpner neste. Du trenger også riktig by, lager, distribusjon og regional ledelse. Kontrollspennet krever prioriteringer; avvikling gir bare halv etableringskapital tilbake.</p><div class="ring-tabs">${G.RINGS.slice(1).map((name,i)=>`<button class="button ${territoryRing===i+1?'brass':'ghost'}" data-ring="${i+1}">${i+1} / ${name}</button>`).join('')}</div><div class="project-grid">${G.TERRITORIES.filter(t=>t.ring===territoryRing).map(t=>{const q=G.territoryQuote(s,t.id);return `<article class="council-card"><span class="section-kicker">${G.RINGS[t.ring]} / ${q.bought?'DIN':'VALGBAR ETABLERING'}</span><h2>${t.name}</h2><p><b>${q.role}.</b> ${q.text}</p><p>+${Math.round(q.demand*100)} % fullprisetterspørsel i ${G.CITIES[t.city].name}. Rammeinntekt ${kr(q.gross)} før rivalpress og driftsstrategi. Vedlikehold ${kr(q.upkeep)} / uke. ${s.regional?.model==='partners'?'Partnerne beholder 20 % av regioninntekten.':s.regional?.model==='professional'?'Regionledelsen koster ytterligere 10 000 kr / uke.':'Egen kontroll gir 8 % høyere regioninntekt.'}</p><p class="small">Krever ${G.CITIES[t.city].name}, to etableringer i forrige ring og lager, distribusjon og ledelse på minst nivå ${q.needLevel}.${q.bought?' Rivalpress '+Math.round(a.territories[t.id].pressure)+'/100.':''}</p>${q.bought?`<button class="text-button" data-release="${t.id}">Avvikle området…</button>`:btn('territory',t.id,'Etabler · '+kr(t.cost),s.rankLevel<3||!q.ready||!q.limit||s.cash<t.cost,'button brass')}</article>`;}).join('')}</div>
${s.routes.length?`<h2 class="section-heading">Utvid rutene du allerede har</h2><div class="project-grid">${s.routes.map(r=>{const n=a.routeLevels[r.id]||0,cost=Math.round(500000*Math.pow(1.18,n));return `<article class="council-card"><span class="section-kicker">RUTE ${r.id} / NIVÅ ${n}</span><h2>${G.CITIES[r.city].name} / ${G.GOODS[r.good].name}</h2><p>Kapasitet ${G.routeCapacity(s,r)} per oppgjør. Oppgradering gir plass; mengden velges fortsatt i ruteplanleggeren. Alle priser og risiko vises der.</p>${btn('routeUpgrade',r.id,'Utvid · '+kr(cost),s.rankLevel<3||s.cash<cost,'button ghost')}</article>`;}).join('')}</div>`:''}
<section class="active-project"><h2>Rivalene husker forrige oppgjør.</h2>${s.scale.rivals.map((r,i)=>r.wins||r.losses?`<p>${G.LORDS[i].name}: ${r.wins} tapte maktkamper mot deg. Styrke nå ${G.enemy(s,i)}. Neste kampanje trenger ${6+Math.min(8,r.wins)} leverte måloppgjør; se mål, kostnad og tap i Maktrådet.</p>`:'').join('')||'<p>Hver vunnet maktkamp øker rivalens styrke med 30 % av grunnstyrken, kostnad og tap. Gjentatte seire gir gradvis svakere markedsfordel.</p>'}</section>
<section class="council-requirements"><h2>Hva står igjen når 2036 er over?</h2><p>Imperieverdien bygger på investert produktiv kapital, avtalte driftsinntekter og stabilitet. Kontantbeholdningen gir ingen direkte poeng. ${score.areas} av ${score.totalAreas} områder er aktive; de uendelige nivåene har ingen fullføringsprosent.</p>${s.ended?`<p>Eksporter gjerne runden fra innstillingene før du begynner på nytt.</p><button class="button brass" data-next-mode="standard">Ny standardrunde…</button><button class="button ghost" data-next-mode="dynasty">Ny arverunde…</button>`:'<p>En fullført runde med allianser kan gi en liten bonus i en egen arverunde: opptil 3 % lavere innkjøpspris og 1,5 prosentpoeng lavere tollrisiko. Standardrunder starter alltid uten slike bonuser.</p>'}</section>`;
}
render=function(){const current=view;if(current==='scaling')view='legacy';priorScaleRender();view=current;if(current==='scaling'){$('#screen').innerHTML=scaling();$('#nav [aria-current]')?.removeAttribute('aria-current');$('#nav .active')?.classList.remove('active');const n=$('#nav [data-view="scaling"]');n.classList.add('active');n.setAttribute('aria-current','page');}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.ring){territoryRing=+b.dataset.ring;render();$('#screen .ring-tabs').scrollIntoView({block:'center'});}if(b.dataset.release){const id=b.dataset.release,q=G.territoryQuote(s,id);modal(`<h2>Avvikle ${q.name}?</h2><p>Du får ${kr(q.cost*.5)} tilbake. Områdets inntekt, etterspørsel og vedlikehold opphører. Den historiske etableringen beholdes for ringåpning.</p><button class="button danger-button" id="confirmRelease">Avvikle området</button><button class="button ghost" id="keepTerritory">Behold området</button>`);$('#confirmRelease').onclick=()=>{act('releaseTerritory',id);$('#dialog').close();};$('#keepTerritory').onclick=()=>$('#dialog').close();}if(b.dataset.nextMode){const mode=b.dataset.nextMode;modal(`<h2>Starte en ${mode==='dynasty'?'arverunde':'standardrunde'}?</h2><p>Dette erstatter den lokale lagringen. Eksporter den ferdige runden først hvis du vil beholde den. Arverunder merkes separat og sammenlignes ikke med standardrunder.</p><button class="button brass" id="confirmCampaign">Start ny runde</button><button class="button ghost" id="keepCampaign">Behold runden</button>`);$('#confirmCampaign').onclick=()=>{const next=G.newCampaign(s,mode);if(next){s=next;view='home';save();render();$('#dialog').close();}};$('#keepCampaign').onclick=()=>$('#dialog').close();}});
render();
